if [[ -d completions ]]; then
  scripts=(completions/_*)
else
  scripts=(_*)
fi
scripts=(${scripts:#*.zwc})

echo "│ File       │ Created                   │ Modified                  │";
echo "│ ────────── │ ───────────────────────── │ ───────────────────────── │";
for file in "${scripts[@]}"; do
  created=$(git log --follow --diff-filter=A --format=%aI -- "$file" | tail -1);
  modified=$(git log --follow -1 --format=%aI -- "$file");
  printf "│ %-10s │ %-25s │ %-25s │\n" "${file##*/}" "$created" "$modified";
done | sort -k4,4r -k6,6r;

#!/usr/bin/env bash
set -euo pipefail

server_log=".run/backend.log"
client_log=".run/frontend.log"

tail -n +1 -F "$server_log" "$client_log" 2>/dev/null |
awk -v server="$server_log" -v client="$client_log" '
function switch_to(tag) {
  if (current != "" && current != tag) {
    print "</" current ">"
  }
  if (current != tag) {
    current = tag
    print "<" current ">"
    fflush()
  }
}

$0 == "==> " server " <==" { switch_to("server"); next }
$0 == "==> " client " <==" { switch_to("client"); next }

{
  print
  fflush()
}

END {
  if (current != "") {
    print "</" current ">"
  }
}
'

